-- Run against fictional seed in disposable database. Every assertion aborts on failure.
begin;
create function pg_temp.assert_true(p_condition boolean,p_label text) returns text language plpgsql as $$ begin if p_condition is distinct from true then raise exception 'FAIL: %',p_label; end if; return 'PASS: '||p_label; end $$;
create function pg_temp.assert_rejected(p_sql text,p_pattern text,p_label text) returns text language plpgsql as $$
begin
 begin execute p_sql; exception when others then
  if sqlerrm ~ p_pattern then return 'PASS: '||p_label; end if;
  raise exception 'FAIL: % (unexpected error %)',p_label,sqlerrm;
 end;
 raise exception 'FAIL: % (operation succeeded)',p_label;
end $$;
select pg_temp.assert_true((select driver_commission_percent=0 from public.app_config),'commission defaults zero');
select set_config('test.duration',(select duration_seconds::text from public.placeholder_scheduled_fare(14.55,121.05,13.76,121.05,'sedan')),true);
update public.app_config set mock_route_speed_kph=60;
select pg_temp.assert_true((select duration_seconds<current_setting('test.duration')::integer from public.placeholder_scheduled_fare(14.55,121.05,13.76,121.05,'sedan')),'route estimate consumes configured speed');
update public.app_config set mock_route_speed_kph=30;
select set_config('test.weights',(select matching_weights::text from public.app_config),true);
update public.app_config set matching_weights='{"distance":0,"preferences":0,"reliability":0,"going_home":0,"return_trip":0,"idle":0}';
select pg_temp.assert_true(public.driver_matching_score('20000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000004',25000)=0,'server matching consumes zeroed weights');
update public.app_config set matching_weights=matching_weights||'{"going_home":100}';
select pg_temp.assert_true(public.driver_matching_score('20000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000004',25000)=100,'server Going Home score consumes configured weight');
update public.app_config set matching_weights=matching_weights||'{"going_home":0,"reliability":100}';
select pg_temp.assert_true(public.driver_matching_score('20000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000004',25000)=50,'small reliability sample remains neutral');
update public.app_config set matching_weights=current_setting('test.weights')::jsonb;
select pg_temp.assert_rejected($q$update public.app_config set matching_weights='{"distance":-10}'$q$,'app_config_matching_weights_valid','negative matching weights rejected');

select pg_temp.assert_true(not has_column_privilege('authenticated','public.trips','trip_pin_hash','SELECT'),'PIN hash has no client column grant');
select pg_temp.assert_true(not has_schema_privilege('authenticated','private','USAGE'),'private PIN schema inaccessible');
select pg_temp.assert_true(not exists(select 1 from pg_tables where schemaname='public' and tablename in ('profiles','ride_requests','driver_documents','vehicle_documents','trips','ride_messages','organizations','organization_members','organization_subscriptions','notifications','payments') and not rowsecurity),'critical tables enable RLS');
select pg_temp.assert_true(not has_function_privilege('anon','public.advance_trip(uuid,text,text)','EXECUTE'),'anonymous cannot call lifecycle');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.audit_product_action(text,text,uuid,jsonb)','EXECUTE'),'clients cannot forge audit events');
select pg_temp.assert_true(public.driver_effective_pickup_distance('20000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000004')<1000,'return candidate uses accepted outbound destination');
update public.ride_requests set scheduled_at=(select scheduled_at+interval '3 hours 30 minutes' from public.ride_requests where id='40000000-0000-4000-8000-000000000002') where id='40000000-0000-4000-8000-000000000001';
select pg_temp.assert_true(public.driver_can_take_ride('20000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001'),'exact single30-minute schedule buffer is eligible');
update public.ride_requests set scheduled_at=scheduled_at-interval '1 second' where id='40000000-0000-4000-8000-000000000001';
select pg_temp.assert_true(not public.driver_can_take_ride('20000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001'),'one second short of schedule buffer rejected');
update public.ride_requests set scheduled_at=now()+interval '24 hours' where id='40000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000010',true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.profiles),'passenger cannot read other profiles');
select pg_temp.assert_true((select count(*)=0 from public.ride_requests),'passenger cannot read unrelated bookings');
select pg_temp.assert_true((select count(*)=0 from public.driver_documents),'passenger cannot read driver documents');
select pg_temp.assert_true((select count(*)=0 from public.organization_members),'outsider cannot read corporate memberships');
select pg_temp.assert_true((select count(*)=0 from public.organization_subscriptions),'outsider cannot read subscriptions');
select pg_temp.assert_true((select count(*)=0 from public.notifications),'outsider cannot read notifications');
select pg_temp.assert_rejected($q$update public.profiles set role='admin' where id=auth.uid()$q$,'permission denied','passenger cannot escalate to admin');
select pg_temp.assert_rejected($q$update public.profiles set role='fleet_admin' where id=auth.uid()$q$,'permission denied','passenger cannot escalate to fleet');
select pg_temp.assert_rejected($q$update public.ride_requests set estimated_fare=1$q$,'permission denied','client cannot change fare');
select pg_temp.assert_rejected($q$select public.admin_update_config('{"driver_commission_percent":99}')$q$,'admin role required','passenger cannot change commission');
select pg_temp.assert_rejected($q$select public.get_passenger_trip_pin('40000000-0000-4000-8000-000000000002')$q$,'PIN unavailable','unrelated passenger cannot retrieve PIN');
select pg_temp.assert_rejected($q$select public.send_ride_message('40000000-0000-4000-8000-000000000002','intrusion',gen_random_uuid())$q$,'participant required','unrelated passenger cannot message');
select pg_temp.assert_rejected($q$select public.record_mock_payment_event('40000000-0000-4000-8000-000000000001','forged','paid')$q$,'trusted payment processor required','passenger cannot mark payment paid');
select pg_temp.assert_rejected($q$select public.save_organization_member('{"organization_id":"50000000-0000-4000-8000-000000000003","user_id":"10000000-0000-4000-8000-000000000010","member_role":"manager"}')$q$,'organization manager required','outsider cannot join corporate account');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',true);
set local role authenticated;
select pg_temp.assert_rejected($q$select * from public.find_eligible_drivers('40000000-0000-4000-8000-000000000005')$q$,'operations role required','Fleet A cannot find drivers for corporate booking');
select pg_temp.assert_rejected($q$select public.create_ride_offers('40000000-0000-4000-8000-000000000001')$q$,'operations role required','fleet cannot dispatch unrelated passenger booking');
select pg_temp.assert_rejected($q$select public.manual_assign_ride('40000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002')$q$,'operations role required','fleet cannot assign itself unrelated private booking');
select pg_temp.assert_true((public.get_fleet_resources('50000000-0000-4000-8000-000000000001')->'drivers')::text not like '%current_location%','fleet projection excludes exact location');
select pg_temp.assert_rejected($q$select public.get_partner_referrals('50000000-0000-4000-8000-000000000002')$q$,'partner manager required','Fleet A cannot read Partner B referrals');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.assert_true(length(public.get_passenger_trip_pin('40000000-0000-4000-8000-000000000002'))=6,'assigned passenger gets six digit PIN');
select set_config('test.booking_payload',jsonb_build_object('client_request_id','70000000-0000-4000-8000-000000000001','pickup_address','Demo Airport','pickup_lat',14.55,'pickup_lng',121.05,'dropoff_address','Demo Resort','dropoff_lat',13.76,'dropoff_lng',121.05,'scheduled_at',now()+interval '10 days','vehicle_type','sedan','service_type','scheduled','passenger_count',2,'estimated_fare',1,'driver_earnings',999999)::text,true);
select set_config('test.new_ride',public.create_transport_request(current_setting('test.booking_payload')::jsonb)::text,true);
select pg_temp.assert_true(public.create_transport_request(current_setting('test.booking_payload')::jsonb)::text=current_setting('test.new_ride'),'booking duplicate submission idempotent');
select pg_temp.assert_true((select gross_fare>1 and driver_earnings=gross_fare and platform_commission=0 from public.ride_requests where id=current_setting('test.new_ride')::uuid),'client financial injection ignored and zero commission snapshot');
select set_config('test.message',public.send_ride_message('40000000-0000-4000-8000-000000000002','Demo message','70000000-0000-4000-8000-000000000002')::text,true);
select pg_temp.assert_true(public.send_ride_message('40000000-0000-4000-8000-000000000002','Demo message','70000000-0000-4000-8000-000000000002')::text=current_setting('test.message'),'message replay idempotent');
select pg_temp.assert_rejected($q$select public.advance_trip('40000000-0000-4000-8000-000000000002','heading')$q$,'driver role required','passenger cannot advance trip');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_rejected($q$select public.get_passenger_trip_pin('40000000-0000-4000-8000-000000000002')$q$,'PIN unavailable','assigned driver cannot retrieve passenger PIN');
select pg_temp.assert_rejected($q$select trip_pin_hash from public.trips$q$,'permission denied','driver cannot select PIN hashes');
select pg_temp.assert_true((select count(*)=1 from public.driver_documents),'Driver A sees own license only');
select pg_temp.assert_true((select count(*)=1 from public.ride_messages),'assigned driver sees passenger message');
select pg_temp.assert_rejected($q$select public.advance_trip('40000000-0000-4000-8000-000000000003','start','123456')$q$,'invalid trip action','completed trip cannot restart');
select pg_temp.assert_true(public.advance_trip('40000000-0000-4000-8000-000000000003','complete')='trip_completed','completed trip replay idempotent');
select pg_temp.assert_rejected($q$select public.admin_review_driver('20000000-0000-4000-8000-000000000002','verified')$q$,'operations role required','driver cannot self verify');
select pg_temp.assert_rejected($q$update public.payments set status='paid'$q$,'permission denied','driver cannot change payment status');
reset role;
-- Make a same-day trip to test PIN counters and arrival wait, using trusted fixture setup.
update public.ride_requests set scheduled_at=now()-interval '5 minutes' where id='40000000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.assert_true(public.advance_trip('40000000-0000-4000-8000-000000000002','heading')='driver_en_route','driver heads to pickup');
select pg_temp.assert_true(public.advance_trip('40000000-0000-4000-8000-000000000002','arrived')='driver_arrived','driver arrives');
select pg_temp.assert_rejected($q$select public.advance_trip('40000000-0000-4000-8000-000000000002','no_show')$q$,'waiting period','late arrival cannot instantly claim no-show');
select pg_temp.assert_true(public.advance_trip('40000000-0000-4000-8000-000000000002','start','invalid')='driver_arrived','incorrect PIN cannot start trip');
reset role;
select pg_temp.assert_true((select failed_attempts=1 from private.trip_secrets where ride_request_id='40000000-0000-4000-8000-000000000002'),'incorrect PIN attempt persists');
select set_config('test.pin',(select pin from private.trip_secrets where ride_request_id='40000000-0000-4000-8000-000000000002'),true);
set local role authenticated;
select pg_temp.assert_true(public.advance_trip('40000000-0000-4000-8000-000000000002','start',current_setting('test.pin'))='trip_started','correct PIN starts assigned trip');
select pg_temp.assert_true(public.advance_trip('40000000-0000-4000-8000-000000000002','complete')='trip_completed','driver completes trip');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.payments where ride_request_id='40000000-0000-4000-8000-000000000002'),'completion creates one pending payment');
select pg_temp.assert_true((select final_fare=gross_fare and driver_earnings=gross_fare and platform_commission=0 from public.trips where ride_request_id='40000000-0000-4000-8000-000000000002'),'completion retains server fare snapshot');
-- Existing offer must reject expired, suspended, expired-document and cancelled ride conditions.
select set_config('test.offer',(select id::text from public.ride_offers where ride_request_id='40000000-0000-4000-8000-000000000001'),true);
update public.ride_offers set expires_at=now()-interval '1 minute' where id=current_setting('test.offer')::uuid;
set local role authenticated;
select pg_temp.assert_rejected($q$select public.accept_ride_offer(current_setting('test.offer')::uuid)$q$,'offer expired','expired offer cannot be accepted');
reset role;
update public.ride_offers set expires_at=now()+interval '1 hour' where id=current_setting('test.offer')::uuid;
update public.profiles set account_status='suspended' where id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.assert_rejected($q$select public.accept_ride_offer(current_setting('test.offer')::uuid)$q$,'driver role required','suspended driver cannot accept');
reset role;
update public.profiles set account_status='active' where id='10000000-0000-4000-8000-000000000002';
update public.driver_documents set expires_on=current_date-1 where driver_id='20000000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.assert_rejected($q$select public.accept_ride_offer(current_setting('test.offer')::uuid)$q$,'no longer eligible','expired license cannot accept');
reset role;
update public.driver_documents set expires_on=current_date+365 where driver_id='20000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.cancel_own_ride_request('40000000-0000-4000-8000-000000000001');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.assert_rejected($q$select public.accept_ride_offer(current_setting('test.offer')::uuid)$q$,'no longer available','cancelled booking cannot be accepted');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
update public.app_config set demo_mode=false;
set local role authenticated;
select pg_temp.assert_rejected($q$select public.record_mock_payment_event(current_setting('test.new_ride')::uuid,'demo-disabled','paid')$q$,'explicit demo','mock payment blocked outside explicit demo');
select public.admin_update_config('{"demo_mode":true,"mock_payment_enabled":true}');
select set_config('test.payment',public.record_mock_payment_event(current_setting('test.new_ride')::uuid,'demo-paid','paid')::text,true);
select pg_temp.assert_true(public.record_mock_payment_event(current_setting('test.new_ride')::uuid,'demo-paid','paid')::text=current_setting('test.payment'),'duplicate mock event idempotent');
select pg_temp.assert_rejected($q$select public.record_mock_payment_event(current_setting('test.new_ride')::uuid,'demo-paid','refunded')$q$,'event id conflict','mock event replay payload conflict rejected');
select public.record_mock_payment_event(current_setting('test.new_ride')::uuid,'demo-refund','refunded');
select pg_temp.assert_rejected($q$select public.record_mock_payment_event(current_setting('test.new_ride')::uuid,'demo-pay-again','paid')$q$,'invalid payment transition','refunded payment cannot be paid again');
reset role;
select pg_temp.assert_true((select count(*)=2 from public.payment_events where payment_id=current_setting('test.payment')::uuid),'duplicate mock event did not duplicate ledger');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.assert_rejected($q$select public.request_driver_application()$q$,'active passenger bookings','active passenger cannot convert to driver');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000010',true);
set local role authenticated;
select public.request_driver_application();
select public.request_driver_application();
select pg_temp.assert_true((select role='driver' from public.profiles where id=auth.uid()),'explicit application creates driver role only');
select pg_temp.assert_true((select verification_status='pending' and not online from public.driver_profiles where user_id=auth.uid()),'new driver application pending and offline');
select pg_temp.assert_rejected($q$select public.admin_update_config('{}')$q$,'admin role required','driver enrollment does not grant admin');
reset role;
rollback;
